--region lifecycle

function MidFestivalBtnBossBehavior:__init()
    self.config = {
        id = 103,
        ---@type MidFestivalMainEntryVo
        vo = nil,
        index = 3,
    }
end

function MidFestivalBtnBossBehavior:__delete()
    self.config = nil
end

function MidFestivalBtnBossBehavior:Awake()
    ---@type ActivityMidFestivalComponent
    self._activityMidFestivalComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    SetButtonAction(self.controller.gameObject, Bind(self, self.OnClick))
end

