--region public
function MidFestivalBtnBossBehavior:Refresh()
    self:InitData()
    self:RefreshUI()
end

function MidFestivalBtnBossBehavior:OnClick()
    if not self._IsUnlock then
        local unlockLevel = self._activityMidFestivalComponent:GetBossUnlockLevel()
        local name = self._activityMidFestivalComponent:GetMainQuestName(unlockLevel)
        GameUtils.Toast(localize("通关_name_后解锁", {_name_ = {name}}))
        return
    end
    
    if not self._activityMidFestivalComponent:IsActive() then
        GameUtils.Toast(localize("活动已结束"))
        return
    end
    
    local moduleId = ActivityMidFestivalMgr:GetMidFestivalMainDialogId()
    local homeDojo = self._activityMidFestivalComponent:GetHomeDojo()
    local info = homeDojo.entranceConf[self.config.index]
    ---@type ActivityMidFestivalUtils
    local ActivityMidFestivalUtils = import("Game.Activity.MidFestival.ActivityMidFestivalUtils")
    CS.Engine.UI.UIModule.OpenDialog({ id = info.moduleId, parameters = { entryMgr = ActivityMidFestivalUtils.GetMidFestivalMgr() }},{{id = moduleId}})
end
--endregion public

--region private
function MidFestivalBtnBossBehavior:InitData()
    self._IsActive = self._activityMidFestivalComponent:IsActive()
    self._IsUnlock = self._activityMidFestivalComponent:IsBossUnlock()
    local homeDojo = self._activityMidFestivalComponent:GetHomeDojo()
    local info = homeDojo.entranceConf[self.config.index]
    self.config.id = info.id
    self.config.vo = ActivityMidFestivalMgr:LoadMainEntryVoById(self.config.id)
end

function MidFestivalBtnBossBehavior:RefreshUI()
    if not string.isEmpty(self.config.vo.name) then
        CfUtils.FillText(self.Text, self.config.vo.name)
    end
    CfUtils.FillText(self.Lock.transform:Find("Text").gameObject, localize("未解锁"))
    if not string.isEmpty(self.config.vo.unlockPicture) then
        CfUtils.FillImage(self.ImgBoss, self.config.vo.unlockPicture)
    end
    if not string.isEmpty(self.config.vo.lockPicture) then
        CfUtils.FillImage(self.ImgBossLock, self.config.vo.lockPicture)
    end

    self:RefreshStatus()
    self:RefreshRedPoint()
end

function MidFestivalBtnBossBehavior:RefreshStatus()
    CfUtils.SetActive(self.ImgBoss, self._IsActive and self._IsUnlock)
    CfUtils.SetActive(self.ImgBossLock, not self._IsActive or not self._IsUnlock)
    CfUtils.SetActive(self.Lock, not self._IsActive or not self._IsUnlock)
end

function MidFestivalBtnBossBehavior:RefreshRedPoint()
    if not self._IsActive or not self._IsUnlock then
        return
    end
    local homeDojo = self._activityMidFestivalComponent:GetHomeDojo()
    local hasRedPoint = homeDojo.bossHurtTips == 0
    CfUtils.SetActive(self.TabNode.transform:Find("redPoint"), hasRedPoint)
end
--endregion private

return MidFestivalBtnBossBehavior
